#include <iomanip>
#include <iostream>
#include <string>

int main() {
    int n;
    if (!(std::cin >> n)) {
        return 0;
    }
    int total = 0;
    for (int i = 0; i < n; i++) {
        std::string name;
        int score;
        std::cin >> name >> score;
        total += score;
        std::cout << std::left << std::setw(12) << name << std::right << std::setw(6) << score << '\n';
    }
    std::cout << std::left << std::setw(12) << "total" << std::right << std::setw(6) << total << '\n';
    return 0;
}

