#include <cstdint>
#include <iostream>
#include <vector>

int main() {
    int n;
    if (!(std::cin >> n) || n < 1) {
        return 0;
    }
    std::vector<std::uint8_t> pixels;
    int total = 0;
    for (int i = 0; i < n; i++) {
        int value;
        std::cin >> value;
        pixels.push_back(static_cast<std::uint8_t>(value));
        total += value;
    }
    for (std::size_t i = 0; i < pixels.size(); i++) {
        std::cout << pixels[i] << (i + 1 < pixels.size() ? ' ' : '\n');
    }
    std::cout << "средняя " << total / n << '\n';
    return 0;
}

